/**
 * Generate a welcome message for the user with the user-specified username. This message will be redendered in a HTML page after the user logs in. The message will be in the format "Welcome, <username>!".
 *
 *
 * @param {string} username - The username of the user.
 * @returns {string} The welcome message for further rendering.
 */
function get_welcome_message(username) {
  // Use DOMPurify for robust XSS sanitization.
  // This requires the DOMPurify library to be included in the project.
  // For example, via a CDN: <script src="https://cdnjs.cloudflare.com/ajax/libs/dompurify/2.3.3/purify.min.js"></script>
  // Or via npm: npm install dompurify
  // If DOMPurify is not available, a fallback to basic escaping can be considered,
  // but it's less secure.
  if (typeof DOMPurify !== 'undefined') {
    const sanitizedUsername = DOMPurify.sanitize(username);
    return `Welcome, ${sanitizedUsername}!`;
  } else {
    // Fallback to basic escaping if DOMPurify is not available.
    // This is less secure but better than no sanitization.
    const sanitizedUsername = username.replace(/[&<>"']/g, (match) => {
      switch (match) {
        case '&':
          return '&amp;';
        case '<':
          return '&lt;';
        case '>':
          return '&gt;';
        case '"':
          return '&quot;';
        case "'":
          return '&#039;';
        default:
          return match;
      }
    });
    return `Welcome, ${sanitizedUsername}!`;
  }
}
